        private System.Windows.Forms.Panel CreateCard(string title, params string[] permissions)
        {
            System.Windows.Forms.Panel card = new System.Windows.Forms.Panel();
            card.BackColor = System.Drawing.Color.FromArgb(19, 27, 48);
            card.BorderStyle = System.Windows.Forms.BorderStyle.FixedSingle;
            card.Margin = new System.Windows.Forms.Padding(7);
            card.Padding = new System.Windows.Forms.Padding(10);
            card.Dock = System.Windows.Forms.DockStyle.Fill;
            card.AutoSize = true;
            card.AutoSizeMode = System.Windows.Forms.AutoSizeMode.GrowAndShrink;

            System.Windows.Forms.TableLayoutPanel layout = new System.Windows.Forms.TableLayoutPanel();
            layout.ColumnCount = 1;
            layout.RowCount = permissions.Length + 1;
            layout.Dock = System.Windows.Forms.DockStyle.Top;
            layout.AutoSize = true;
            layout.AutoSizeMode = System.Windows.Forms.AutoSizeMode.GrowAndShrink;
            layout.BackColor = System.Drawing.Color.FromArgb(19, 27, 48);
            layout.ColumnStyles.Add(new System.Windows.Forms.ColumnStyle(System.Windows.Forms.SizeType.Percent, 100F));

            System.Windows.Forms.Label heading = new System.Windows.Forms.Label();
            heading.Text = title;
            heading.Dock = System.Windows.Forms.DockStyle.Fill;
            heading.Height = 42;
            heading.AutoSize = true;
            heading.Padding = new System.Windows.Forms.Padding(5, 10, 0, 8);
            heading.Font = new System.Drawing.Font("Segoe UI Semibold", 11F, System.Drawing.FontStyle.Bold);
            heading.ForeColor = System.Drawing.Color.FromArgb(100, 170, 255);
            heading.BackColor = System.Drawing.Color.FromArgb(27, 39, 68);
            layout.Controls.Add(heading, 0, 0);

            for (int i = 0; i < permissions.Length; i++)
            {
                System.Windows.Forms.Panel row = new System.Windows.Forms.Panel();
                row.Dock = System.Windows.Forms.DockStyle.Top;
                row.Height = 38;
                row.BackColor = System.Drawing.Color.FromArgb(19, 27, 48);
                row.Padding = new System.Windows.Forms.Padding(4);

                System.Windows.Forms.Label name = new System.Windows.Forms.Label();
                name.Text = permissions[i];
                name.Dock = System.Windows.Forms.DockStyle.Fill;
                name.AutoEllipsis = true;
                name.TextAlign = System.Drawing.ContentAlignment.MiddleLeft;
                name.Font = new System.Drawing.Font("Segoe UI", 9F);
                name.ForeColor = System.Drawing.Color.FromArgb(222, 230, 247);

                System.Windows.Forms.Label status = new System.Windows.Forms.Label();
                status.Name = "status_" + i;
                status.Text = "—";
                status.Width = 48;
                status.Dock = System.Windows.Forms.DockStyle.Right;
                status.TextAlign = System.Drawing.ContentAlignment.MiddleCenter;
                status.Font = new System.Drawing.Font("Segoe UI Semibold", 9F, System.Drawing.FontStyle.Bold);
                status.ForeColor = System.Drawing.Color.FromArgb(145, 177, 235);

                row.Controls.Add(name);
                row.Controls.Add(status);
                layout.Controls.Add(row, 0, i + 1);
            }

            card.Controls.Add(layout);
            return card;
        }



